import math

def find_n(factorial):
    n = int(math.sqrt(2 * math.pi * len(str(factorial))) * (len(str(factorial)) / math.e))
    while True:
        if math.factorial(n) < factorial:
            n += 1
        elif math.factorial(n) > factorial:
            n -= 1
        else:
            return n

